import { test, expect } from '@playwright/test';

test.describe('Dropdown Menu Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should navigate dropdown items using keyboard arrow keys', async ({ page }) => {
    await page.getByRole('button', { name: 'Dropdown' }).click(); // Replace with actual dropdown button name
    await expect(page.getByRole('menu')).toBeVisible();

    await page.keyboard.press('ArrowDown');
    await expect(page.getByRole('menuitem', { name: 'Item 1' })).toHaveFocus();

    await page.keyboard.press('ArrowDown');
    await expect(page.getByRole('menuitem', { name: 'Item 2' })).toHaveFocus();
  });

  test('should select dropdown item using Enter key', async ({ page }) => {
    await page.getByRole('button', { name: 'Dropdown' }).click(); // Replace with actual dropdown button name
    await page.keyboard.press('ArrowDown');
    await page.keyboard.press('Enter');

    await expect(page.getByRole('button', { name: 'Dropdown' })).toHaveText('Item 1'); // Replace with expected selected item
  });
});
